local OrganBuilder = {}
local INSTRUMENTS = {
    pipe_organ = { name = "Cevne orgle", woodCost = 10, metalCost = 15, leatherCost = 5, time = 60, cost = 3000, soundQuality = 50, faith = 20, prestige = 25, happiness = 10, description = "Velike cerkevne orgle." },
    portative = { name = "Portativ", woodCost = 3, metalCost = 2, leatherCost = 1, time = 10, cost = 300, soundQuality = 20, happiness = 3, description = "Majhne prenosne orgle." },
    positive_organ = { name = "Pozitiv", woodCost = 5, metalCost = 5, leatherCost = 2, time = 20, cost = 800, soundQuality = 30, prestige = 5, happiness = 5, description = "Srednje orgle." },
    regal = { name = "Regal", woodCost = 4, metalCost = 3, leatherCost = 3, time = 14, cost = 500, soundQuality = 25, happiness = 4, description = "Prenosne orgle z jeziki." },
    harpsichord = { name = "Čembalo", woodCost = 8, metalCost = 3, time = 25, cost = 1000, soundQuality = 35, prestige = 10, happiness = 8, description = "Glasbilo s tipkami." },
    clavichord = { name = "Klavikord", woodCost = 5, metalCost = 2, time = 15, cost = 500, soundQuality = 25, happiness = 5, description = "Tiho glasbilo za dom." },
}
local BUILDINGS = {
    workshop = { name = "Orglarska delavnica", cost = { gold = 500, wood = 200, metal = 50 }, upkeep = 15, qualityBonus = 10 },
    pipe_workshop = { name = "Cevna delavnica", cost = { gold = 1000, wood = 200, stone = 200, metal = 100 }, upkeep = 25, qualityBonus = 20 },
    voicing_room = { name = "Intonacijska soba", cost = { gold = 1500, wood = 300, stone = 300, metal = 50 }, upkeep = 35, qualityBonus = 30 },
    royal_organ_works = { name = "Kraljevska orglarna", cost = { gold = 6000, wood = 500, stone = 1000, metal = 200 }, upkeep = 120, qualityBonus = 45, prestigeBonus = 25 },
}
OrganBuilder.woodStock = 15; OrganBuilder.metalStock = 10; OrganBuilder.leatherStock = 5
OrganBuilder.productStock = {}; OrganBuilder.buildings = {}; OrganBuilder.organBuilder = nil; OrganBuilder.activeBuilding = {}; OrganBuilder.totalInstruments = 0; OrganBuilder.dayTimer = 0
function OrganBuilder.init() OrganBuilder.woodStock=15; OrganBuilder.metalStock=10; OrganBuilder.leatherStock=5; OrganBuilder.productStock={}; OrganBuilder.buildings={}; OrganBuilder.organBuilder=nil; OrganBuilder.activeBuilding={}; OrganBuilder.totalInstruments=0; OrganBuilder.dayTimer=0; print("[OrganBuilder] Royal Organ Builder & Instrument Maker System initialized (6 instruments, 4 buildings)") end
function OrganBuilder.hireOrganBuilder(n,s) s=s or math.random(45,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OrganBuilder.organBuilder={name=n or ("Orglar "..math.random(1,99)),skill=s,hiredDay=os.time(),instrumentsBuilt=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Orglar najet: %s (spretnost: %d)",OrganBuilder.organBuilder.name,s),"success") end; return true end
function OrganBuilder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OrganBuilder.build(id) local ok,e=OrganBuilder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OrganBuilder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OrganBuilder.getQualityBonus() local b=0; for _,bd in ipairs(OrganBuilder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OrganBuilder.canBuild_instrument(it) local d=INSTRUMENTS[it]; if not d then return false,"Neznan instrument" end; if d.woodCost and OrganBuilder.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.metalCost and OrganBuilder.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.leatherCost and OrganBuilder.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if #OrganBuilder.buildings==0 then return false,"Potrebna orglarska delavnica" end; if not OrganBuilder.organBuilder then return false,"Potreben orglar" end; return true end
function OrganBuilder.build_instrument(it) local ok,e=OrganBuilder.canBuild_instrument(it); if not ok then return false,e end; local d=INSTRUMENTS[it]; if d.woodCost then OrganBuilder.woodStock=OrganBuilder.woodStock-d.woodCost end; if d.metalCost then OrganBuilder.metalStock=OrganBuilder.metalStock-d.metalCost end; if d.leatherCost then OrganBuilder.leatherStock=OrganBuilder.leatherStock-d.leatherCost end; local t=d.time; if OrganBuilder.organBuilder then t=math.max(2,t-math.floor(OrganBuilder.organBuilder.skill/8)) end; table.insert(OrganBuilder.activeBuilding,{id="instr_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),instrumentType=it,instrumentName=d.name,cost=d.cost,soundQuality=d.soundQuality or 0,faith=d.faith or 0,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function OrganBuilder.completeBuilding(b) local q=1.0+(OrganBuilder.getQualityBonus()/100); if OrganBuilder.organBuilder then q=q+(OrganBuilder.organBuilder.skill/200) end; q=math.min(2.5,q); OrganBuilder.productStock[b.instrumentType]=(OrganBuilder.productStock[b.instrumentType] or 0)+1; OrganBuilder.totalInstruments=OrganBuilder.totalInstruments+1; if _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+b.happiness*q) end; if b.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,b.faith) end; if b.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+b.prestige) end; if OrganBuilder.organBuilder then OrganBuilder.organBuilder.instrumentsBuilt=OrganBuilder.organBuilder.instrumentsBuilt+1; if math.random()<0.15 then OrganBuilder.organBuilder.skill=math.min(100,OrganBuilder.organBuilder.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Instrument izdelan: %s (kakovost: %.1f)",b.instrumentName,q),"success") end end
function OrganBuilder.update(dt) if not _G.state then return end; OrganBuilder.dayTimer=OrganBuilder.dayTimer+dt; if OrganBuilder.dayTimer>=30 then OrganBuilder.dayTimer=0; for i=#OrganBuilder.activeBuilding,1,-1 do local b=OrganBuilder.activeBuilding[i]; b.daysRemaining=b.daysRemaining-1; if b.daysRemaining<=0 then OrganBuilder.completeBuilding(b); table.remove(OrganBuilder.activeBuilding,i) end end; local tu=0; for _,bd in ipairs(OrganBuilder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OrganBuilder.organBuilder then tu=tu+20 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OrganBuilder.getStats() return {woodStock=OrganBuilder.woodStock,metalStock=OrganBuilder.metalStock,leatherStock=OrganBuilder.leatherStock,productStock=OrganBuilder.productStock,numBuildings=#OrganBuilder.buildings,hasOrganBuilder=OrganBuilder.organBuilder~=nil,organBuilderName=OrganBuilder.organBuilder and OrganBuilder.organBuilder.name or "—",organBuilderSkill=OrganBuilder.organBuilder and OrganBuilder.organBuilder.skill or 0,activeBuilding=#OrganBuilder.activeBuilding,totalInstruments=OrganBuilder.totalInstruments} end
return OrganBuilder
